import{_ as n,o as h,c as i,a2 as c}from"./chunks/framework.mRCPFc5l.js";const l=JSON.parse('{"title":"Khác gì mục tiêu điểm số","description":"","frontmatter":{},"headers":[],"relativePath":"portrait/khac-diem-so.md","filePath":"portrait/khac-diem-so.md"}'),a={name:"portrait/khac-diem-so.md"};function o(r,t,u,m,g,e){return h(),i("div",null,[...t[0]||(t[0]=[c('<h1 id="khac-gi-muc-tieu-điem-so" tabindex="-1">Khác gì mục tiêu điểm số <a class="header-anchor" href="#khac-gi-muc-tieu-điem-so" aria-label="Permalink to &quot;Khác gì mục tiêu điểm số&quot;">​</a></h1><p>Trên trang này# Khác gì mục tiêu điểm số <a href="#khac-gi-muc-tieu-điem-so">​</a> Mục tiêu điểm số là một con số cần đạt. Portrait là một con người cần trở thành. Khác biệt nghe có vẻ triết lý, nhưng hệ quả của nó rất cụ thể — nó đổi hẳn cách một gia đình ra quyết định.</p><h2 id="bon-khac-biet-thuc-te-​" tabindex="-1">Bốn khác biệt thực tế <a href="#bon-khac-biet-thuc-te">​</a> <a class="header-anchor" href="#bon-khac-biet-thuc-te-​" aria-label="Permalink to &quot;Bốn khác biệt thực tế [​](#bon-khac-biet-thuc-te)&quot;">​</a></h2><p><strong>Mục tiêu điểm số có ngày hết hạn. Portrait thì không.</strong> &quot;9.0 môn Toán học kỳ này&quot; — thi xong là hết. Rồi lại đặt mục tiêu mới. Sau sáu năm là mười hai mục tiêu rời rạc, không cái nào nối với cái nào. &quot;Con là người dám hỏi khi không hiểu&quot; thì đúng suốt sáu năm đó và cả sau này. <strong>Mục tiêu điểm số có thể đạt bằng cách sai.</strong> Học tủ, luyện đúng dạng đề, chọn phần dễ ăn điểm — tất cả đều làm điểm lên mà không làm con giỏi hơn. Portrait không có đường tắt: không ai &quot;học tủ&quot; được việc trở thành người tự quản lý được việc học của mình. <strong>Mục tiêu điểm số chỉ nói về trường học. Portrait nói về cả cuộc đời.</strong> Thể thao, âm nhạc, bạn bè, sức khoẻ, sở thích, sự tò mò — không thứ nào có trong bảng điểm, và phần lớn chúng quan trọng hơn khi con 30 tuổi. <strong>Mục tiêu điểm số không cần con đồng ý. Portrait thì cần.</strong> Bố mẹ có thể đặt &quot;phải được 9.0&quot; mà không hỏi con. Nhưng &quot;con muốn trở thành người như thế nào&quot; mà con không tham gia thì đó không phải portrait của con — đó là kế hoạch áp lên con.</p><h2 id="cung-mot-quyet-đinh-hai-cach-nhin-​" tabindex="-1">Cùng một quyết định, hai cách nhìn <a href="#cung-mot-quyet-đinh-hai-cach-nhin">​</a> <a class="header-anchor" href="#cung-mot-quyet-đinh-hai-cach-nhin-​" aria-label="Permalink to &quot;Cùng một quyết định, hai cách nhìn [​](#cung-mot-quyet-đinh-hai-cach-nhin)&quot;">​</a></h2><p>Con lớp 8, đang học thêm Toán ba buổi một tuần, điểm khoảng 7.5. Có cơ hội tham gia một câu lạc bộ robot, nhưng phải bỏ một buổi học thêm. Nhìn qua mục tiêu điểm sốBỏ một buổi Toán → điểm có thể tụt. Câu lạc bộ robot không nằm trong môn thi nào. Quyết định: không tham gia. Nhìn qua PortraitPortrait ghi &quot;thích chế tạo&quot;, &quot;muốn làm một dự án từ đầu tới cuối&quot;, &quot;cần bớt sợ sai&quot;. Robot phục vụ cả ba. Toán 7.5 → 7.8 phục vụ cái gì? Quyết định: tham gia, và xem lại xem ba buổi học thêm có thật sự cần cả ba không. Không phải cách nhìn thứ hai luôn thắng. Nếu con đang ôn thi chuyên và còn ba tháng, cách nhìn thứ nhất có lý. Điểm ở đây là: <strong>có Portrait thì câu hỏi được đặt ra</strong>. Không có Portrait thì mặc định luôn là &quot;ưu tiên điểm&quot;, và không ai kịp nhận ra rằng mình vừa mặc định một điều gì đó.</p><h2 id="điem-so-van-o-trong-portrait-​" tabindex="-1">Điểm số vẫn ở trong Portrait <a href="#điem-so-van-o-trong-portrait">​</a> <a class="header-anchor" href="#điem-so-van-o-trong-portrait-​" aria-label="Permalink to &quot;Điểm số vẫn ở trong Portrait [​](#điem-so-van-o-trong-portrait)&quot;">​</a></h2><p>Nemo12 không chống lại điểm số hay kỳ thi. Mục tiêu học thuật là <strong>một trong mười mảng</strong> của Portrait, và nó là mảng quan trọng thật — cánh cửa vào trường tốt là chuyện có thật. Khác biệt là ở <strong>vị trí</strong>. Điểm số là một mảng trong mười, không phải toàn bộ bức tranh. Khi nó là toàn bộ bức tranh, mọi thứ khác trong đời một đứa trẻ tự động trở thành &quot;thứ làm mất tập trung&quot;.</p><h2 id="đieu-xay-ra-voi-nhung-gia-đinh-chi-co-muc-tieu-điem-so-​" tabindex="-1">Điều xảy ra với những gia đình chỉ có mục tiêu điểm số <a href="#đieu-xay-ra-voi-nhung-gia-đinh-chi-co-muc-tieu-điem-so">​</a> <a class="header-anchor" href="#đieu-xay-ra-voi-nhung-gia-đinh-chi-co-muc-tieu-điem-so-​" aria-label="Permalink to &quot;Điều xảy ra với những gia đình chỉ có mục tiêu điểm số [​](#đieu-xay-ra-voi-nhung-gia-đinh-chi-co-muc-tieu-điem-so)&quot;">​</a></h2><p>Hai chuyện, đều đã thấy nhiều lần: <strong>Đạt được rồi thì trống rỗng.</strong> Con đỗ trường chuyên — mục tiêu duy nhất suốt ba năm — rồi mất phương hướng hoàn toàn trong học kỳ đầu. Không ai chuẩn bị cho câu hỏi &quot;rồi sao nữa&quot;. <strong>Không đạt được thì sụp đổ.</strong> Trượt một kỳ thi bị hiểu thành thất bại toàn diện, vì không còn cách nào khác để đứa trẻ nhìn về bản thân nó. Một gia đình có Portrait vẫn còn chín mảng khác nguyên vẹn để nói chuyện. Cách thử nhanh Hỏi: <em>&quot;Nếu bỏ hết điểm số và kỳ thi ra khỏi câu chuyện, mình còn nói gì được về con?&quot;</em> Nếu câu trả lời ngắn — đó chính là lý do Portrait tồn tại. Mục tiêu điểm số hỏi &quot;con đạt được gì&quot;. Portrait hỏi &quot;con trở thành ai&quot;. Cả đời chỉ có câu thứ hai là còn được hỏi mãi. <a href="/portrait/vi-sao-can">Vì sao gia đình cần hình dung này →</a></p>',10)])])}const k=n(a,[["render",o]]);export{l as __pageData,k as default};
